// Measures how common each yoga is, so the app can show an honest rarity badge
// ("only 8% of charts have this") instead of calling a coin-flip a superpower.
//
//   node tools/yoga-frequency.js [sampleSize]
//
// Writes public/yoga-rarity.js. Re-run and commit the result whenever
// server/yogas.js or public/yoga-names.js changes.
//
// Sampling — these choices are the whole ballgame, so they're stated here and
// echoed into the generated file:
//   * Birth dates uniform over BIRTH_FROM..BIRTH_TO, the app's target audience.
//     Yoga frequency genuinely drifts with era (the outer planets move slowly),
//     so a wider range would report different numbers.
//   * Time of birth uniform over 24h.
//   * Birthplace drawn from the built-in gazetteer (server/cities.js), which is
//     India-weighted — matching who this app is for. Place only reaches the
//     yogas via the ascendant, but that drives every house-based yoga.
//   * Deterministic LCG, so a re-run with the same size reproduces the table.
//
// Frequencies are aggregated BY ALIAS, not by yoga key: a chart with four
// separate Raja Yogas counts once toward "the come-up", because the badge
// answers "do I have this?" not "how many variants did I hit?".
const fs = require("fs");
const path = require("path");

const ROOT = path.join(__dirname, "..");
const { computeChart } = require(path.join(ROOT, "server/astro.js"));
const { CITIES } = require(path.join(ROOT, "server/cities.js"));
const { yogaAlias } = require(path.join(ROOT, "public/yoga-names.js"));

const N = Math.max(100, parseInt(process.argv[2], 10) || 8000);
const BIRTH_FROM = 1995;
const BIRTH_TO = 2010;
const SEED = 20260725;

// Deterministic PRNG (a re-run must reproduce the committed table exactly).
let seed = SEED;
const rnd = () => ((seed = (seed * 1103515245 + 12345) % 2147483648) / 2147483648);
const pick = arr => arr[Math.floor(rnd() * arr.length)];

// Day-of-month capped at 28 so every month is equally weighted and no sampled
// date is invalid; this slightly under-weights days 29-31, which is immaterial
// for yoga frequency (planets don't care which day of the month it is).
function sampleBirth() {
  const city = pick(CITIES);
  return {
    year: BIRTH_FROM + Math.floor(rnd() * (BIRTH_TO - BIRTH_FROM + 1)),
    month: 1 + Math.floor(rnd() * 12),
    day: 1 + Math.floor(rnd() * 28),
    hour: Math.floor(rnd() * 24),
    minute: Math.floor(rnd() * 60),
    lat: city.lat,
    lon: city.lon,
    tz: city.tz,
    nodeMode: "jupiter"
  };
}

const counts = new Map();   // alias -> charts containing it (counted once each)
const meta = new Map();     // alias -> { category, sanskrit }
let failures = 0;

const started = Date.now();
for (let i = 0; i < N; i++) {
  let c;
  try {
    c = computeChart(sampleBirth());
  } catch (_) {
    failures++;
    continue;
  }
  const seenHere = new Set();
  for (const y of c.yogas || []) {
    const alias = yogaAlias(y);
    if (!alias || seenHere.has(alias)) continue;
    seenHere.add(alias);
    counts.set(alias, (counts.get(alias) || 0) + 1);
    if (!meta.has(alias)) {
      meta.set(alias, { category: y.category, sanskrit: String(y.name).replace(/\s*\(.*$/, "").trim() });
    }
  }
  if ((i + 1) % 500 === 0) {
    const pct = (((i + 1) / N) * 100).toFixed(0);
    process.stdout.write(`  ${i + 1}/${N} (${pct}%) — ${Math.round((Date.now() - started) / 1000)}s\n`);
  }
}

const analysed = N - failures;
const rows = [...counts.entries()]
  .map(([alias, n]) => ({ alias, n, pct: (n / analysed) * 100, ...meta.get(alias) }))
  .sort((a, b) => a.pct - b.pct);

// 95% CI half-width, so the generated file is honest about its own precision.
const moe = p => 1.96 * Math.sqrt(((p / 100) * (1 - p / 100)) / analysed) * 100;

const body = rows
  .map(r => {
    const pad = " ".repeat(Math.max(0, 26 - JSON.stringify(r.alias).length));
    return `  ${JSON.stringify(r.alias)}:${pad}${r.pct.toFixed(1)},` +
      ` // ${r.sanskrit} · ${r.category} · n=${r.n} · ±${moe(r.pct).toFixed(1)}`;
  })
  .join("\n");

const out = `// GENERATED by tools/yoga-frequency.js — do not edit by hand.
// Re-run: node tools/yoga-frequency.js ${N}
//
// Share of charts (%) containing at least one yoga with this name.
// Sample: ${analysed.toLocaleString("en-US")} charts, births ${BIRTH_FROM}-${BIRTH_TO}, times uniform over 24h,
// birthplaces drawn from the built-in gazetteer (India-weighted). Seed ${SEED}.
// These are frequencies in THAT sample, not in the world — a different era or
// geography would shift them. Trailing comment on each line: Sanskrit name,
// category, raw count, and the 95% confidence half-width in points.
const YOGA_RARITY = {
${body}
};

if (typeof module !== "undefined" && module.exports) module.exports = { YOGA_RARITY };
`;

const dest = path.join(ROOT, "public/yoga-rarity.js");
fs.writeFileSync(dest, out);

console.log(`\nAnalysed ${analysed} charts in ${Math.round((Date.now() - started) / 1000)}s` +
  (failures ? ` (${failures} failed)` : ""));
console.log(`Wrote ${path.relative(ROOT, dest)} — ${rows.length} distinct yoga names\n`);
for (const r of rows) {
  console.log(`  ${r.pct.toFixed(1).padStart(5)}%  ±${moe(r.pct).toFixed(1)}  ${r.alias.padEnd(26)} ${r.category}`);
}
